from .keysight import Keysight
from ..exceptions import InternalError, UnsupportedOperation


class KeysightN9020A(Keysight):
    """ Handles operations on Keysight N9020A type of signal analyzer """

    _SUPPORTED_MODES = (Keysight._SA_MODE, )

    _GET_MARKER_Y_AXIS_MODES = (Keysight._SA_MODE, )

    _OPERATION_DELAY_TIME = Keysight._DEVICE_LOADING_TIME * 0.8

    def set_sweep_acquisition(self, acquisition, timeout=10):
        """
        Sets given sweep acquisition on the device.
        :param acquisition: value from allowed range
        :type acquisition: int
        :param timeout: time to wait for individual steps of this operation to be finished
        :type timeout: int
        :raises IncorrectOperation: when device is not in appropriate mode or acquisition is out of allowed range
        :raises UnsupportedOperation: when this operation is not supported by used signal analyzer model
        """
        raise UnsupportedOperation(self._UNSUPPORTED_OPERATION_MSG.format(self.__class__.__name__,
                                                                          self.set_sweep_acquisition.__name__))

    def get_sweep_acquisition(self, timeout=10):
        """
        Gets current sweep acquisition from the device.
        :param timeout: time to wait for individual steps of this operation to be finished; defaults to 10 seconds
        :type timeout: int
        :return: device's current sweep acquisition
        :rtype: int
        :raises IncorrectOperation: when device is not in appropriate mode
        :raises IncorrectResponse: when device responses with unhandled or incorrect message
        :raises UnsupportedOperation: when this operation is not supported by used signal analyzer model
        """
        raise UnsupportedOperation(self._UNSUPPORTED_OPERATION_MSG.format(self.__class__.__name__,
                                                                          self.get_sweep_acquisition.__name__))

    def measure_channel_power(self, timeout=10):
        """
        Starts channel power measurement and gets current channel power measurement from the device.
        :param timeout: time to wait for individual steps of this operation to be finished; defaults to 10 seconds
        :type timeout: int
        :return: device's current channel power measurement
        :rtype: float
        :raises IncorrectOperation: when device is not in appropriate mode
        :raises IncorrectResponse: when device responses with unhandled or incorrect message
        """
        self._check_if_operation_is_allowed(self.measure_channel_power, self._MEASURE_CHANNEL_POWER_MODES)

        self.set_channel_power_measurement(timeout)
        channel_power = self._execute_query(self._MEASURE_CHANNEL_POWER_CMD, timeout, self._OPERATION_DELAY_TIME)

        self._check_response(channel_power)
        return self._convert_response_to_float(channel_power)

    def get_marker_y_axis(self, marker_id=1, timeout=10):
        """
        Gets Y axis value of given marker from the device.
        :param marker_id: ID of marker for which Y axis value should be read; defaults to 1
        :type marker_id: int
        :param timeout: time to wait for individual steps of this operation to be finished; defaults to 10 seconds
        :type timeout: int
        :return: Y axis value of given marker
        :rtype: float
        :raises IncorrectOperation: when device is not in appropriate mode or marker ID is out of allowed range
        :raises IncorrectResponse: when device responses with unhandled or incorrect message
        :raises UnsupportedOperation: when this operation is not supported by used signal analyzer model
        """
        self._check_if_operation_is_allowed(self.get_marker_y_axis, self._GET_MARKER_Y_AXIS_MODES)
        self._check_marker_id(marker_id, self._get_allowed_marker_id_range())
        command = self._GET_MARKER_Y_AXIS.format(marker_id)
        marker_y_axis = self._execute_query(command, timeout, self._OPERATION_DELAY_TIME)
        return self._convert_response_to_float(marker_y_axis)

    def _get_allowed_center_frequency_range(self):
        """
        Gets center frequency range which is allowed in current operating mode.
        :return: allowed center frequency range
        :rtype: tuple(int, int)
        :raises InternalError: when allowed frequency span is not specified for current mode
        """
        if self._mode in self._SUPPORTED_MODES:
            return -79999995, 3699999995
        else:
            raise InternalError("Allowed center frequency range not specified for '{}' mode".format(self._mode))

    def _get_allowed_frequency_span_range(self):
        """
        Gets frequency span range which is allowed in current operating mode.
        :return: allowed frequency span range
        :rtype: tuple(int, int)
        :raises InternalError: when allowed frequency span is not specified for current mode
        """
        if self._mode in self._SUPPORTED_MODES:
            return 0, 3700000000
        else:
            raise InternalError("Allowed frequency span range not specified for '{}' mode".format(self._mode))

    def _get_allowed_bandwidth_range(self):
        """
        Gets bandwidth range which is allowed in current operating mode.
        :return: allowed bandwidth range
        :rtype: tuple(int, int)
        :raises InternalError: when allowed bandwidth is not specified for current mode
        """
        if self._mode in self._SUPPORTED_MODES:
            return 1, 8000000
        else:
            raise InternalError("Allowed bandwidth range not specified for '{}' mode".format(self._mode))

    def _get_allowed_resolution_bandwidth_range(self):
        """
        Gets resolution bandwidth range which is allowed in current operating mode.
        :return: allowed resolution bandwidth range
        :rtype: tuple(int, int)
        :raises InternalError: when allowed resolution bandwidth is not specified for current mode
        """
        if self._mode in self._SUPPORTED_MODES:
            return 1, 8000000
        else:
            raise InternalError("Allowed resolution bandwidth range not specified for '{}' mode".format(self._mode))

    def _get_allowed_video_bandwidth_range(self):
        """
        Gets video bandwidth range which is allowed in current operating mode.
        :return: allowed video bandwidth range
        :rtype: tuple(int, int)
        :raises InternalError: when allowed video bandwidth is not specified for current mode
        """
        if self._mode in self._SUPPORTED_MODES:
            return 1, 50000000
        else:
            raise InternalError("Allowed video bandwidth range not specified for '{}' mode".format(self._mode))

    def _get_allowed_sweep_points_range(self):
        """
        Gets sweep points range which is allowed in current operating mode.
        :return: allowed sweep points range
        :rtype: tuple(int, int)
        :raises InternalError: when allowed sweep points are not specified for current mode
        """
        if self._mode in self._SUPPORTED_MODES:
            return 1, 20001
        else:
            raise InternalError("Allowed sweep points range not specified for '{}' mode".format(self._mode))

    def _get_allowed_attenuation_range(self):
        """
        Gets attenuation range which is allowed in current operating mode.
        :return: allowed attenuation range
        :rtype: tuple(int, int)
        :raises InternalError: when allowed attenuation is not specified for current mode
        """
        if self._mode in self._SUPPORTED_MODES:
            return 0, 70
        else:
            raise InternalError("Allowed attenuation range not specified for '{}' mode".format(self._mode))

    def _get_allowed_external_gain_range(self):
        """
        Gets external gain range which is allowed in current operating mode.
        :return: allowed external gain range
        :rtype: tuple(float, float)
        :raises InternalError: when allowed external gain is not specified for current mode
        """
        if self._mode in self._SUPPORTED_MODES:
            return -81.9, 81.9
        else:
            raise InternalError("Allowed external gain range not specified for '{}' mode".format(self._mode))

    def _get_allowed_channel_integrating_bandwidth(self):
        """
        Gets channel integrating bandwidth range which is allowed in current operating mode.
        :return: allowed channel integrating bandwidth range
        :rtype: tuple(int, int)
        :raises InternalError: when allowed channel integrating bandwidth is not specified for current mode
        """
        if self._mode in self._SUPPORTED_MODES:
            return 100, 1000000000
        else:
            raise InternalError("Allowed channel integrating bandwidth range not specified for '{}' mode".format(
                self._mode))

    def _get_allowed_marker_id_range(self):
        """
        Gets marker ID range which is allowed in current operating mode.
        :return: allowed marker ID range
        :rtype: tuple(int, int)
        :raises InternalError: when allowed marker ID is not specified for current mode
        """
        if self._mode in self._SUPPORTED_MODES:
            return 1, 12
        else:
            raise InternalError("Allowed marker ID range not specified for '{}' mode".format(self._mode))
